(()=>{const codes=['en','zh-TW','zh-CN','ja','ko','es'];window.SSStorage={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v);return true}catch{return false}},remove(k){try{localStorage.removeItem(k);return true}catch{return false}},read(k,f=null){try{return JSON.parse(this.get(k)||'null')??f}catch{return f}}};function normalize(v){if(typeof v!=='string')return null;const s=v.replace(/_/g,'-').toLowerCase();if(s.includes('hant')||s==='zh-tw'||s==='zh-hk')return'zh-TW';if(s.includes('hans')||s==='zh-cn'||s==='zh-sg')return'zh-CN';if(s==='zh')return'zh-TW';return codes.find(c=>s===c.toLowerCase()||s.startsWith(c.toLowerCase()+'-'))||null}let handler=null,busy=false;function get(){return normalize(SSStorage.read('spotsense-preferences-v1',{}).language)||normalize(SSStorage.read('pokerTrainer_v1',{}).lang)||(navigator.languages||[navigator.language]).map(normalize).find(Boolean)||'zh-TW'}function apply(value,persist=true){const lang=normalize(value);if(!lang)throw new RangeError('Unsupported language');if(persist){const p=SSStorage.read('spotsense-preferences-v1',{});p.language=lang;SSStorage.set('spotsense-preferences-v1',JSON.stringify(p));const d=SSStorage.read('pokerTrainer_v1');if(d){d.lang=lang;SSStorage.set('pokerTrainer_v1',JSON.stringify(d))}}if(handler&&!busy){busy=true;try{handler(lang)}finally{busy=false}}document.dispatchEvent(new CustomEvent('sslocale:change',{detail:{language:lang}}));return lang}window.SSLocale={codes,normalize,get,set:apply,trainer(fn){handler=fn}};addEventListener('storage',e=>{if(e.key==='spotsense-preferences-v1')apply(get(),false)});function viewport(){const v=window.visualViewport;document.documentElement.style.setProperty('--vh',(v?v.height:innerHeight)+'px');document.documentElement.style.setProperty('--vtop',(v?v.offsetTop:0)+'px')}viewport();addEventListener('resize',viewport);if(window.visualViewport){visualViewport.addEventListener('resize',viewport);visualViewport.addEventListener('scroll',viewport)}})();